void consume(tcp::socket& sock) {
  auto buf = std::make_shared<std::array<char, 4096>>();
  sock.async_receive(boost::asio::buffer(*buf),
      [&sock, buf](boost::system::error_code ec, std::size_t n) {
        if (ec) return;                  // closed or error
        handle_message(buf->data(), n);  // the listener
        consume(sock);                   // re-arm for the next delivery
      });
}
