boost::asio::awaitable<void> consume(tcp::socket sock) {
  std::array<char, 4096> buf;
  for (;;) {
    auto [ec, n] = co_await sock.async_receive(
        boost::asio::buffer(buf), boost::asio::as_tuple);
    if (ec) co_return;                // closed or error
    handle_message(buf.data(), n);    // the listener
  }
}
